sys_script_client.script:
var _canSubmit = false;

function onSubmit() {
    // 1. Limpar mensagens anteriores para garantir que não bloqueiem o g_form.submit()
    g_form.hideFieldMsg('date');
    g_form.hideFieldMsg('course');

    if (_canSubmit) {
        _canSubmit = false;
        return true;
    }

    var dateValue = g_form.getValue('date');
    var courseId = g_form.getValue('course');

    if (!dateValue) {
        g_form.showFieldMsg('date', 'Error: Date is required.', 'error');
        return false;
    }

    if (!courseId) {
        g_form.showFieldMsg('course', 'Error: Course is required.', 'error');
        return false;
    }

    // STRY 11 — Check if date is before tomorrow
    var selectedDateMs = getDateFromFormat(dateValue, g_user_date_format);
    var today = new Date();
    var tomorrow = new Date(today.getFullYear(), today.getMonth(), today.getDate() + 1);

    if (selectedDateMs < tomorrow.getTime()) {
        g_form.showFieldMsg('date', 'Error: You can only schedule training sessions for tomorrow or later.', 'error');
        return false;
    }

    // 2. Capturar qual botão foi clicado (Save, Update, Submit, etc.)
    var actionName = g_form.getActionName();

    // STRY 3 — Check duplicate date via GlideAjax
    var ga = new GlideAjax('x_1960572_training.TrainingHubUtils');
    ga.addParam('sysparm_name', 'checkDuplicateDate');
    ga.addParam('sysparm_course', courseId);
    ga.addParam('sysparm_date', dateValue);
    ga.addParam('sysparm_id', g_form.getUniqueValue());

    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            g_form.showFieldMsg('date', 'Error: A training session for this course is already scheduled on this date!', 'error');
            return;
        }

        _canSubmit = true;

        // 3. Submeter o formulário passando a ação original
        if (actionName) {
            g_form.submit(actionName);
        } else {
            g_form.submit();
        }
    });

    return false;
}
